(() => {
const {e,icon}=F;
const modal=(title,body,footer='',cls='')=>({title,body,footer,cls});
const cancel=()=>F.btn('취소','close-modal');
const close=()=>F.btn('닫기','close-modal');
F.modalScreens=new Set(['sources','broadcast-settings','connection','broadcast-details','broadcast-end','share','info','quality','nickname','manual','report-content','clip-create','donate','membership','mission','poll','rewards','update','devices','raid']);
F.modalBackground=id=>['sources','broadcast-settings','connection','broadcast-details','broadcast-end','update'].includes(id)?'studio':id==='manual'?'live':'watch';
F.modals={
 sources:(state)=>{
 const monitor=state==='전체 화면'||(F.sourceTab==='전체 화면'&&!['프로그램 창','불러오는 중','응답 지연','창 닫힘','대상 없음'].includes(state));
 const items=monitor?[{id:'monitor-1',kind:'monitor',title:'모니터 1',sub:'2560 × 1440 · 주 모니터',scene:'code'},{id:'monitor-2',kind:'monitor',title:'모니터 2',sub:'1920 × 1080',scene:'design'}]:[{id:'editor',kind:'editor',title:'workspace.ts — Visual Studio Code',scene:'code'},{id:'discord',kind:'discord',title:'작업실 — Discord',scene:'board'},{id:'claude',kind:'claude',title:'Claude',scene:'design'},{id:'chrome',kind:'chrome',title:'프로젝트 문서 — Chrome',scene:'map'},{id:'game',kind:'game',title:'픽셀 어드벤처',scene:'game'},{id:'night',kind:'chrome',title:'도시의 밤 — Chrome',scene:'night'}];
 const status={'불러오는 중':'불러오는 중','응답 지연':'응답이 늦어요','창 닫힘':'창이 닫혔어요'}[state];
 const body=`<div class="source-tabs" role="tablist" aria-label="공유할 화면 종류"><button role="tab" data-action="source-tab" data-tab="프로그램 창" aria-selected="${!monitor}">${icon('monitor')}프로그램 창</button><button role="tab" data-action="source-tab" data-tab="전체 화면" aria-selected="${monitor}">${icon('monitor')}전체 화면</button></div><div class="source-dialog-body">${state==='대상 없음'?F.empty('공유할 수 있는 창이 없어요','프로그램을 연 뒤 목록을 새로고침해 주세요.','새로고침','source-refresh','monitor'):`<div class="source-grid">${items.map((item,i)=>{const failed=status&&i===1;const waiting=state==='불러오는 중'&&i>0;const selected=F.source===item.id;return `<div class="source-item"><button class="source-card ${selected?'selected':''}" data-action="source-select" data-source="${item.id}" aria-pressed="${selected}" aria-label="${e(item.title)}" title="${e(item.title+(item.sub?' · '+item.sub:''))}"><span class="source-thumb">${failed||waiting?`<span class="thumb-status">${waiting?'<span class="spinner"></span>':icon('monitor')}<span>${waiting?'불러오는 중':status}</span></span>`:F.scene(item.scene,item.title+' 미리보기')}${selected?`<span class="selected-tick">${icon('check')}</span>`:''}</span><span class="source-name">${F.appIcon(item.kind)}<span class="${item.sub?'monitor-copy':'name'}">${item.sub?`<span class="name">${e(item.title)}</span><small>${e(item.sub)}</small>`:e(item.title)}</span></span></button>${failed&&state==='응답 지연'?F.btn('다시 시도','source-retry','refresh','thumb-retry'):''}</div>`;}).join('')}</div>`}</div>`;
 return modal('공유할 화면',body,`${F.btn('새로고침','source-refresh','refresh','ghost')}<span style="flex:1"></span>${cancel()}${F.btn('선택','source-confirm','','primary',state==='대상 없음'?'disabled':'')}`,'wide source-dialog');
 },
 'broadcast-settings':(state)=>{
 const manual=state==='수동 비트레이트'||!F.bitrateAuto;
 const invalid=state==='지원 범위 오류';
 return modal('방송 설정',`<div class="two-column"><div class="settings-section"><h3>영상</h3>${F.field('해상도',F.choice('resolution',F.values.resolution,['360p','480p','720p','1080p','1440p','2160p (4K)']))}${F.field('프레임률',F.choice('fps',F.values.fps,['30 fps','60 fps','90 fps','120 fps','144 fps','165 fps']),invalid?'이 장치에서 선택한 설정을 적용할 수 없어요.':'',invalid)}<button class="advanced-summary" data-action="advanced" aria-expanded="${manual||invalid}">${icon('gear')}고급 설정${icon('chevron')}</button><div class="advanced-body" ${!manual&&!invalid?'hidden':''}><div class="field"><div class="field-inline"><label for="bitrate-value">비트레이트</label>${F.toggle('자동',!manual,'bitrate-auto')}</div><div class="row"><input id="bitrate-value" name="bitrate" aria-label="비트레이트" type="number" min="0.5" max="200" step="0.5" value="${F.values.bitrate}" ${!manual?'disabled':''}><span class="smalltext">Mbps</span></div><small>${!manual?'송출 해상도와 프레임률을 기준으로 계산해요.':'직접 입력한 값을 유지해요.'}</small></div>${F.field('코덱',F.choice('codec',F.values.codec,['H.264','HEVC','AV1']))}</div></div><div class="settings-section"><h3>오디오</h3><div class="audio-row"><div class="audio-head">${icon('volume')}시스템 소리<span>80%</span></div><input type="range" min="0" max="100" value="80" aria-label="시스템 소리 음량"><div class="audio-meter"></div></div><div class="audio-row"><div class="audio-head">${icon('mic')}마이크<span>60%</span></div>${F.choice('microphone','기본 마이크',['기본 마이크','마이크 사용 안 함'])}<div style="margin-top:10px"><input type="range" min="0" max="100" value="60" aria-label="마이크 음량"></div><div class="audio-meter mic"></div></div><h3 style="margin:25px 0 8px">녹화</h3>${F.setting('방송 녹화','',F.toggle('',true,'recording'))}${F.field('저장 한도',F.choice('storage','100 GB',['50 GB','100 GB','200 GB','직접 입력']))}</div></div>`,`${cancel()}${F.btn('저장','apply-settings','','primary')}`,'medium');
 },
 connection:(state)=>modal('연결 설정',`${F.field('서버 주소',F.input('server','relay.example.test','서버 IP 또는 호스트 이름'))}<div class="field-pair">${F.field('송출 포트',F.input('publish-port','8554','','number','min="1" max="65535"'))}${F.field('시청 포트',F.input('view-port','443','','number','min="1" max="65535"'))}</div>${F.field('스트림 ID',F.input('stream-id','spring'))}${F.field('스트림 키',`<div class="row">${F.input('stream-key','sample-key-hidden','','password')}${F.btn('','show-key','key','icon','aria-label="스트림 키 표시"')}</div>`)}${F.field('시청 연결',F.choice('protocol','HTTPS',['HTTPS','HTTP']))}${state==='연결 확인 중'?'<div class="row help"><span class="spinner"></span>서버 연결을 확인하고 있어요.</div>':state==='연결 실패'?'<div class="inline-notice error">서버에 연결하지 못했어요. 주소와 포트를 확인해 주세요.</div>':''}`,`${F.btn('연결 확인','connection-test','refresh')}<span style="flex:1"></span>${cancel()}${F.btn('저장','save-connection','','primary')}`),
 'broadcast-details':(state)=>modal('방송 정보 수정',`${F.field('방송 제목',F.input('broadcast-title','조용히 개발해요 · 화면 공유 작업실'),'방송 제목을 입력해 주세요.'.repeat(state==='입력 오류'?1:0),state==='입력 오류')}${F.field('카테고리',F.choice('category','개발 · 작업',['개발 · 작업','게임','일상 · 이야기','디자인 · 창작','지식 · 탐색']))}${F.field('태그',F.input('tags','개발, 작업실, 함께하기'))}${F.field('공개 범위',F.choice('visibility','전체 공개',['전체 공개','링크가 있는 사람','멤버십 전용']))}`,`${cancel()}${F.btn('저장','save-broadcast-details','','primary')}`),
 'broadcast-end':(state)=>state==='종료 요약'?modal('방송이 종료되었어요',`${F.stats([['방송 시간','1시간 24분'],['최고 시청자 수','216명'],['평균 시청자 수','128명'],['새 팔로워','12명']])}<p class="help">녹화 파일은 녹화 관리에서 확인할 수 있어요.</p>`,`${F.go('recordings','녹화 관리')}${F.go('live','라이브로 이동','','primary')}`,'medium'):modal('방송을 종료할까요?',`<p style="font-size:16px;line-height:1.8">방송을 종료하면 시청자에게 종료 화면이 표시돼요.</p><label class="check-row"><input type="checkbox" checked><span>방송 종료 후 녹화 파일 보관</span></label>`,`${cancel()}${F.btn('방송 종료','finish-broadcast','','danger')}`),
 share:(state)=>modal('방송 링크',`<div class="row" style="margin-bottom:22px">${F.avatar('봄','round')}<div><strong style="font-size:16px">개발하는 봄</strong><p class="help">조용히 개발해요 · 화면 공유 작업실</p></div></div><label for="share-link">방송 링크</label><div class="share-url"><input id="share-link" readonly value="https://frame.example/@spring/live" aria-label="방송 링크">${F.btn(state==='복사 완료'?'복사됨':'복사','copy-link',state==='복사 완료'?'check':'copy')}</div><div style="margin-top:22px">${F.choice('share-option','현재 방송',['현재 방송','현재 재생 시점부터'])}</div>`,`${F.btn('임베드 코드','embed-code','code')}${close()}`),
 info:()=>modal('방송 정보',`<div style="margin-bottom:20px"><strong style="font-size:18px;line-height:1.6">조용히 개발해요 · 화면 공유 작업실</strong><div class="row" style="margin-top:5px">${F.go('channel','개발하는 봄','','small ghost')}<span class="help">개발 · 작업</span></div></div>${F.dl([['방송 시간','01:24:36'],['시청자 수','128명'],['재생 화질','자동 (1080p)'],['실제 FPS','59.9 fps'],['목표 프레임률','60 fps'],['비트레이트','8.1 Mbps'],['오디오','시스템 소리 + 마이크']])}<button class="advanced-summary" data-action="advanced" aria-expanded="false" style="margin-top:15px">${icon('gear')}고급 정보${icon('chevron')}</button><div class="advanced-body" hidden>${F.dl([['코덱','H.264'],['연결 방식','WebRTC'],['스트림 ID','spring']])}</div>`,`${F.go('report-content','신고하기','','ghost')}${close()}`),
 nickname:(state)=>modal('닉네임 설정',`<form id="nickname-form">${F.field('닉네임',F.input('nickname',F.nickname,'닉네임 입력','text','maxlength="20" autocomplete="nickname"'),state==='입력 오류'?'닉네임은 1~20자로 입력해 주세요.':'채팅에서 사용할 이름이에요.',state==='입력 오류')}</form>`,`${cancel()}<button class="primary" type="submit" form="nickname-form">저장</button>`),
 manual:(state)=>modal('직접 연결',`${F.field('서버 주소',F.input('viewer-server','relay.example.test','서버 IP 또는 호스트 이름'))}<div class="field-pair">${F.field('시청 포트',F.input('viewer-port','443','','number','min="1" max="65535"'))}${F.field('연결 방식',F.choice('viewer-protocol','HTTPS',['HTTPS','HTTP']))}</div>${F.field('스트림 ID',F.input('viewer-stream','spring'))}${state==='연결 중'?'<div class="row help"><span class="spinner"></span>방송에 연결하고 있어요.</div>':state==='연결 실패'?'<div class="inline-notice error">방송에 연결하지 못했어요. 입력한 주소를 확인해 주세요.</div>':''}`,`${cancel()}${F.btn('연결','manual-connect','','primary')}`),
 'report-content':(state)=>state==='접수 완료'?modal('신고 접수',`<div class="modal-success"><span class="success-icon">${icon('check')}</span><h3>신고가 접수되었어요.</h3><p>내용을 확인한 뒤 필요한 조치를 진행해요.</p></div>`,close()):modal('신고하기',`${F.field('신고 사유',F.choice('report-reason','사유 선택',['부적절한 콘텐츠','도배 및 광고','권리 침해','개인정보 노출','기타']))}${F.field('상세 내용','<textarea name="report-detail" rows="4" aria-label="신고 상세 내용" placeholder="문제가 된 내용을 알려주세요."></textarea>')}`,`${cancel()}${F.btn('신고 접수','submit-report','','primary')}`),
 'clip-create':(state)=>state==='생성 완료'?modal('클립 만들기',`<div class="modal-success"><span class="success-icon">${icon('check')}</span><h3>클립이 만들어졌어요.</h3><p>클립 목록에서 확인할 수 있어요.</p></div>`,`${F.go('clip-watch','클립 보기','','primary')}`):modal('클립 만들기',`<div class="studio-preview" style="border-radius:7px;margin-bottom:20px">${F.scene('code')}</div><input type="range" min="0" max="60" value="42" aria-label="클립 구간"><div class="field-pair">${F.field('시작',F.input('clip-start','00:18:30'))}${F.field('종료',F.input('clip-end','00:19:12'))}</div>${F.field('클립 제목',F.input('clip-title','','제목을 입력해 주세요.'))}${state==='처리 중'?'<div class="row help"><span class="spinner"></span>클립을 만들고 있어요.</div>':''}`,`${cancel()}${F.btn('클립 만들기','create-clip','','primary')}`,'medium'),
 donate:(state)=>{
 if(state==='완료')return modal('후원하기',`<div class="modal-success"><span class="success-icon">${icon('heart')}</span><h3>마음을 전했어요.</h3><p>개발하는 봄 님에게 5,000원을 후원했어요.</p></div>`,close());
 if(state==='처리 중')return modal('후원하기','<div class="modal-success"><span class="spinner"></span><h3>결제를 확인하고 있어요.</h3><p>처리가 끝날 때까지 잠시 기다려 주세요.</p></div>',F.btn('확인','donation-complete','','primary'));
 return modal('후원하기',`<div class="row" style="margin-bottom:23px">${F.avatar('봄','round')}<strong>개발하는 봄</strong></div>${F.tabs([['메시지'],['음성'],['영상']],'메시지')}<div class="amount-options">${['1,000','5,000','10,000','직접 입력'].map(a=>F.btn(a==='직접 입력'?a:a+'원','amount','',a==='5,000'?'selected':'',`data-amount="${a}"`)).join('')}</div>${F.field('금액',F.input('donation-amount','5000','','number','min="1000"'))}${F.field('메시지','<textarea rows="3" name="donation-message" aria-label="후원 메시지" placeholder="응원의 메시지를 남겨주세요."></textarea>')}${F.field('결제 방법',F.choice('payment','결제 방법 선택',['카드','간편결제']))}${state==='결제 실패'?'<div class="inline-notice error">결제를 완료하지 못했어요. 결제 수단을 확인해 주세요.</div>':''}<label class="check-row"><input id="payment-consent" type="checkbox"><span>결제 내용과 취소·환불 기준을 확인했어요.</span></label>`,`${cancel()}${F.btn('5,000원 후원하기','donate','','primary')}`);
 },
 membership:(state)=>state==='가입 완료'?modal('멤버십',`<div class="modal-success"><span class="success-icon">${icon('gift')}</span><h3>멤버십에 가입했어요.</h3><p>가입 혜택은 채널에서 확인할 수 있어요.</p></div>`,close()):modal('멤버십 가입',`<div class="row" style="margin-bottom:20px">${F.avatar('봄','round')}<div><strong>개발하는 봄</strong><p class="help">월 4,900원</p></div></div><div class="panel" style="padding:18px;margin-bottom:20px">${F.setting('멤버십 배지','채팅에서 함께한 시간을 표시해요.',icon('shield'))}${F.setting('전용 이모티콘','채팅에서 사용할 수 있어요.',icon('heart'))}${F.setting('멤버십 방송','공개 범위가 지정된 방송을 시청해요.',icon('video'))}</div>${F.field('결제 방법',F.choice('membership-payment','결제 방법 선택',['카드','간편결제']))}<label class="check-row"><input type="checkbox"><span>월 정기 결제와 해지 기준을 확인했어요.</span></label>${state==='결제 실패'?'<div class="inline-notice error" style="margin-top:14px">결제를 완료하지 못했어요.</div>':''}`,`${F.btn('멤버십 선물','gift-membership','gift')}${F.btn('가입하기','join-membership','','primary')}`),
 mission:(state)=>state==='완료'||state==='실패'?modal('미션',`<div class="modal-success"><span class="success-icon">${icon(state==='완료'?'check':'close')}</span><h3>${state==='완료'?'미션을 완료했어요.':'미션이 종료되었어요.'}</h3><p>처리 내역은 후원·미션 기록에서 확인할 수 있어요.</p></div>`,close()):state==='진행 중'?modal('진행 중인 미션',`<h3 style="font-size:20px;margin-bottom:14px">오늘의 기능 완성하기</h3>${F.dl([['제안자','모아'],['유형','무료 미션'],['남은 시간','24분 32초'],['상태',F.pill('진행 중')]])}`,close()):modal('미션 제안',`${F.field('미션 유형',F.choice('mission-type','무료 미션',['무료 미션','미션 후원']))}${F.field('미션 제목',F.input('mission-title','','도전할 내용을 입력해 주세요.'))}${F.field('완료 조건','<textarea rows="3" name="mission-condition" aria-label="완료 조건" placeholder="완료를 판단할 수 있게 작성해 주세요."></textarea>')}${F.field('제한 시간',F.choice('mission-time','방송 종료 전',['30분','1시간','방송 종료 전']))}<div id="mission-fee" hidden>${F.field('후원 금액',F.input('mission-amount','10000','','number'))}</div>`,`${cancel()}${F.btn('제안하기','send-mission','','primary')}`),
 poll:(state)=>modal('투표 및 질문',`${F.tabs([['투표'],['질문']],'투표')}${F.pollMarkup(state)}<div style="margin-top:24px">${F.field('방송자에게 질문',F.input('question','','질문을 입력해 주세요.'))}</div>`,`${F.btn('질문 보내기','send-question','','primary')}${close()}`),
 rewards:(state)=>state==='교환 완료'?modal('포인트 보상',`<div class="modal-success"><span class="success-icon">${icon('gift')}</span><h3>보상을 신청했어요.</h3><p>신청 내역은 포인트 기록에서 확인할 수 있어요.</p></div>`,close()):modal('포인트 보상',`<div class="row" style="justify-content:space-between;margin-bottom:20px"><span class="smalltext">내 포인트</span><strong style="font-size:23px">${state==='포인트 부족'?'200':'3,400'} P</strong></div><div class="reward-grid">${[['target','다음 작업 제안','1,000 P'],['sun','화면 테마 선택','2,000 P'],['heart','응원 보내기','500 P']].map(([ico,name,points])=>`<button class="reward-item" data-action="redeem-reward">${icon(ico)}<strong>${name}</strong><small>${points}</small></button>`).join('')}</div>${state==='포인트 부족'?'<p class="error-text" style="font-size:13px;color:#b53342;margin-top:18px">포인트가 부족해요. 필요한 포인트를 확인해 주세요.</p>':''}`,`${F.btn('포인트 기록','point-history','history')}${close()}`),
 update:(state)=>modal('앱 업데이트',state==='최신 버전'?`<div class="modal-success"><span class="success-icon">${icon('check')}</span><h3>최신 버전을 사용 중이에요.</h3><p>현재 버전 0.7.0</p></div>`:`<h3 style="font-size:20px;margin-bottom:10px">새 버전이 준비되었어요.</h3><p class="help" style="margin-bottom:22px">0.6.1 → 0.7.0</p>${state==='다운로드 중'?'<div class="progress-track"><span style="width:58%"></span></div><p class="help" style="margin-top:9px">58% 다운로드 중</p>':'<p class="help">업데이트 내용과 적용 시점을 확인한 뒤 진행해 주세요.</p>'}`,`${close()}${state==='최신 버전'?'':F.btn(state==='다운로드 중'?'일시정지':'업데이트','download-update','download','primary')}`),
 devices:(state)=>modal('다른 기기에서 보기',state==='기기 없음'?F.empty('주변 기기를 찾지 못했어요','기기의 연결 상태를 확인해 주세요.','다시 찾기','retry','cast'):`<p class="help" style="margin-bottom:16px">연결할 기기를 선택해 주세요.</p>${F.setting('거실 TV','사용 가능',F.btn('연결','connect-device','cast','small'))}${F.setting('회의실 화면','사용 가능',F.btn('연결','connect-device','cast','small'))}${state==='연결 실패'?'<div class="inline-notice error">기기에 연결하지 못했어요.</div>':''}`,close()),
 raid:(state)=>state==='완료'?modal('다른 방송으로 연결',`<div class="modal-success"><span class="success-icon">${icon('users')}</span><h3>시청자에게 다음 방송을 안내했어요.</h3><p>이동은 각 시청자가 선택할 수 있어요.</p></div>`,close()):state==='이동 확인'?modal('다음 방송을 안내할까요?',`<h3 style="margin-bottom:12px">오늘도 한 장씩, 디자인 작업</h3><p class="help">서재 님의 채널로 이동할 수 있는 안내를 현재 채팅에 표시해요.</p>`,`${cancel()}${F.btn('안내하기','finish-raid','','primary')}`):modal('다른 방송으로 연결',`${F.field('채널 검색',F.input('raid-search','','채널 이름 검색'))}<div class="catalog-grid">${F.card(F.broadcasts[1])}</div>`,`${cancel()}${F.btn('이 방송 선택','confirm-raid','','primary')}`,'medium')
};
F.renderModal=(id,state)=>{if(!F.modals[id])throw new Error('Missing modal renderer: '+id);return F.modals[id](state);};
})();



